def generate_review(analysis):
    risks_md = "\n".join([f"- {risk}" for risk in analysis['risks']])
    improvements_md = "\n".join([f"- {imp}" for imp in analysis['improvements']])
    
    template = f"""# PR Review Report

## 📝 Summary of Changes
{analysis['summary']}

## ⚠️ Identified Risks
{risks_md}

## 💡 Improvement Suggestions
{improvements_md}

## 📊 Confidence Score
**{analysis['confidence']}**

---
*Generated by the PR Review Sub-Agent*
"""
    return template
